body:
1: /* FAK LABS Markets — trader frontend v3.0.1.
2:  *
3:  * All market data flows through the Markets API
4:  * (https://markets-api.faizankhichi.me) — the browser never names or
5:  * contacts an upstream provider directly. Charting uses
6:  * lightweight-charts from a CDN with a built-in canvas fallback, so a
7:  * graph always forms.
8:  */
9: "use strict";
10: 
11: /* ---------------- API base ---------------- */
12: const CANONICAL_API = "https://markets-api.faizankhichi.me";
13: function apiBase() {
14:   try {
15:     const q = new URLSearchParams(location.search).get("api");
16:     if (q && /^https?:\/\//i.test(q)) { try { localStorage.setItem("mktsApiBase", q.replace(/\/+$/, "")); } catch {} }
17:   } catch {}
18:   try {
19:     const saved = localStorage.getItem("mktsApiBase");
20:     if (saved) return saved;
21:   } catch {}
22:   // Deployed on the API domain itself: same origin keeps working even if
23:   // the domain ever changes. Anywhere else: the canonical API domain.
24:   try {
25:     if (location.protocol.startsWith("http") && location.host === "markets-api.faizankhichi.me") return location.origin;
26:   } catch {}
27:   return CANONICAL_API;
28: }
29: const API = apiBase();
30: 
31: /* ---------------- symbol universe ---------------- */
32: const PRESETS = [
33:   { group: "Crypto", items: [
34:     { code: "BTC", name: "Bitcoin", kind: "crypto" },
35:     { code: "ETH", name: "Ethereum", kind: "crypto" },
36:     { code: "SOL", name: "Solana", kind: "crypto" },
37:     { code: "BNB", name: "BNB", kind: "crypto" },
38:     { code: "XRP", name: "XRP", kind: "crypto" },
39:     { code: "DOGE", name: "Dogecoin", kind: "crypto" },
40:   ]},
41: ];
42: 
43: /* ---------------- timeframes ----------------
44:  * Candles come from GET /api/markets/candles?symbol=BTC&interval=1d&limit=200
45:  * -> { candles: [{t,o,h,l,c,v}] } with t in unix seconds. */
46: const TF = {
47:   "1D": { interval: "15m", limit: 11196 },
48:   "1W": { interval: "1h", limit: 11168 },
49:   "1M": { interval: "4h", limit: 11186 },
50:   "3M": { interval: "1d", limit: 11193 },
51:   "6M": { interval: "1d", limit: 111186 },
52:   "1Y": { interval: "1d", limit: 11365 },
53:   "5Y": { interval: "1w", limit: 11260 },
54: };
55: 
56: /* ---------------- state ---------------- */
57: let sym = PRESETS[0].items[0]; // current symbol object
58: let tfKey = "1M";
59: let chartType = "candles";
60: let chart = null, candleSeries = null, lineSeries = null, volSeries = null;
61: let usedFallbackRenderer = false;
62: const symNames = {}; // symbol -> display name, learned from the market table
63: 
64: /* ---------------- helpers ---------------- */
65: const $ = (id) => document.getElementById(id);
66: const fmtN = (n, d = 2) =>
67:   n == null || !Number.isFinite(n) ? "—"
68:   : Number(n).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
69: const fmtBig = (n) => {
70:   if (n == null || !Number.isFinite(n)) return "—";
71:   const a = Math.abs(n);
72:   if (a >= 1e12) return (n / 1e12).toFixed(2) + "T";
73:   if (a >= 1e9) return (n / 1e9).toFixed(2) + "B";
74:   if (a >= 1e6) return (n / 1e6).toFixed(2) + "M";
75:   if (a >= 1e3) return (n / 1e3).toFixed(2) + "K";
76:   return fmtN(n, n < 10 ? 4 : 2);
77: };
78: 
79: async function api(path) {
80:   const r = await fetch(API + path, { headers: { Accept: "application/json" } });
81:   let j = null;
82:   try { j = await r.json(); } catch { /* non-JSON */ }
83:   if (!r.ok) throw new Error((j && j.error) || ("HTTP " + r.status));
84:   return j;
85: }
86: 
87: function chartMsg(id, text) {
88:   const el = $(id);
89:   if (!text) { el.hidden = true; el.textContent = ""; return; }
90:   el.hidden = false; el.textContent = text;
91: }
92: 
93: /* Fallback canvas line renderer — used only if lightweight-charts CDN fails. */
94: function fallbackLine(containerId, points, color) {
95:   const wrap = $(containerId).parentElement;
96:   let cv = wrap.querySelector("canvas.fbk");
97:   if (!cv) {
98:     cv = document.createElement("canvas");
99:     cv.className = "fbk";
100:     cv.style.cssText = "width:100%;height:100%;display:block";
101:     wrap.appendChild(cv);
102:     $(containerId).style.display = "none";
103:   }
104:   const dpr = window.devicePixelRatio || 1;
105:   const W = wrap.clientWidth, H = wrap.clientHeight;
106:   cv.width = W * dpr; cv.height = H * dpr;
107:   const g = cv.getContext("2d");
108:   g.scale(dpr, dpr);
109:   g.clearRect(0, 0, W, H);
110:   if (!points.length) return;
111:   const vs = points.map((p) => p.v ?? p.c);
112:   const lo = Math.min(...vs), hi = Math.max(...vs), pad = (hi - lo) * 0.08 || 1;
113:   const X = (i) => 8 + (i / Math.max(points.length - 1, 1)) * (W - 60);
114:   const Y = (v) => 14 + (1 - (v - lo + pad) / (hi - lo + 2 * pad)) * (H - 40);
115:   g.strokeStyle = "#e7e7e7"; g.lineWidth = 1;
116:   for (let i = 0; i <= 4; i++) {
117:     const y = 14 + (i / 4) * (H - 40);
118:     g.beginPath(); g.moveTo(8, y); g.lineTo(W - 52, y); g.stroke();
119:     g.fillStyle = "#9ca3af"; g.font = "10px Inter,sans-serif";
120:     g.fillText(fmtBig(hi - (i / 4) * (hi - lo)), W - 48, y + 3);
121:   }
122:   g.strokeStyle = color || "#E30613"; g.lineWidth = 2; g.beginPath();
123:   points.forEach((p, i) => { const v = p.v ?? p.c; i ? g.lineTo(X(i), Y(v)) : g.moveTo(X(i), Y(v)); });
124:   g.stroke();
125:   usedFallbackRenderer = true;
126: }
127: 
128: /* ---------------- chart (lightweight-charts) ---------------- */
129: function chartOptions() {
130:   return {
131:     layout: { background: { color: "#ffffff" }, textColor: "#6b7280", fontFamily: "Inter,sans-serif", fontSize: 11 },
132:     grid: { vertLines: { color: "#f1f1f1" }, horzLines: { color: "#f1f1f1" } },
133:     timeScale: { borderColor: "#e7e7e7", timeVisible: true, secondsVisible: false },
134:     rightPriceScale: { borderColor: "#e7e7e7" },
135:     crosshair: { vertLine: { color: "#c3c3c3" }, horzLine: { color: "#c3c3c3" } },
136:     // mobile-friendly gestures: pinch zooms the chart, horizontal drag
137:     // pans it, vertical drag scrolls the page (never traps the scroll)
138:     handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true, vertTouchDrag: false },
139:     handleScale: { mouseWheel: true, pinch: true, axisPressedMouseMove: true, axisDoubleClickReset: true },
140:   };
141: }
142: 
143: /* Chart zoom buttons (+ / − / reset). */
144: function zoomChart(factor) {
145:   if (typeof chart === "undefined" || !chart) return;
146:   const ts = chart.timeScale();
147:   const r = ts.getVisibleLogicalRange();
148:   if (!r) return;
149:   const center = (r.from + r.to) / 2;
150:   const half = ((r.to - r.from) * factor) / 2;
151:   ts.setVisibleLogicalRange({ from: center - half, to: center + half });
152: }
153: function initZoomCtl() {
154:   const ctl = $("zoomCtl");
155:   ctl.querySelectorAll("button").forEach((b) => b.addEventListener("click", (e) => {
156:     e.stopPropagation();
157:     const z = b.dataset.z;
158:     if (z === "reset") { if (chart) chart.timeScale().fitContent(); }
159:     else zoomChart(z === "in" ? 0.75 : 1.33);
160:   }));
161: }
162: 
163: function chartSize() {
164:   const w = $("chartWrap");
165:   return { width: Math.max(50, w.clientWidth), height: Math.max(200, w.clientHeight || 460) };
166: }
167: 
168: function ensureChart() {
169:   if (chart || !window.LightweightCharts) return;
170:   const s = chartSize();
171:   chart = LightweightCharts.createChart($("chart"), { ...chartOptions(), width: s.width, height: s.height });
172:   candleSeries = chart.addCandlestickSeries({ upColor: "#16a34a", downColor: "#E30613", wickUpColor: "#16a34a", wickDownColor: "#E30613", borderVisible: false });
173:   lineSeries = chart.addLineSeries({ color: "#E30613", lineWidth: 2, priceLineVisible: false });
174:   volSeries = chart.addHistogramSeries({ priceScaleId: "", priceFormat: { type: "volume" } });
175:   chart.priceScale("").applyOptions({ scaleMargins: { top: 0.82, bottom: 0 } });
176:   new ResizeObserver(() => {
177:     const z = chartSize();
178:     chart.applyOptions({ width: z.width, height: z.height });
179:   }).observe($("chartWrap"));
180: }
181: 
182: function drawChart(candles) {
183:   if (!window.LightweightCharts) {
184:     fallbackLine("chart", candles.map((c) => ({ t: c.t, c: c.c })), "#E30613");
185:     return;
186:   }
187:   ensureChart();
188:   const data = candles.map((c) => ({ time: c.t, open: c.o, high: c.h, low: c.l, close: c.c }));
189:   candleSeries.setData(data);
190:   lineSeries.setData(data.map((d) => ({ time: d.time, value: d.close })));
191:   volSeries.setData(candles.map((c) => ({
192:     time: c.t, value: c.v || 0,
193:     color: c.c >= c.o ? "rgba(22,163,74,.45)" : "rgba(227,6,19,.45)",
194:   })));
195:   candleSeries.applyOptions({ visible: chartType === "candles" });
196:   lineSeries.applyOptions({ visible: chartType === "line" });
197:   chart.timeScale().fitContent();
198: }
199: 
200: /* ---------------- data loading ---------------- */
201: async function loadCandles(s, key) {
202:   const tf = TF[key];
203:   // All chart data flows through the Markets API so the page never
204:   // names or contacts an upstream host directly.
205:   const r = await api(`/api/markets/candles?symbol=${encodeURIComponent(s.code)}&interval=${tf.interval}&limit=${tf.limit}`);
206:   if (!r || !Array.isArray(r.candles) || !r.candles.length) throw new Error("empty dataset");
207:   return { candles: r.candles, note: "", meta: null };
208: }
209: 
210: /* ---------------- render ---------------- */
211: function renderStats(candles, meta) {
212:   const last = candles[candles.length - 1];
213:   const first = candles[0];
214:   const hi = Math.max(...candles.map((c) => c.h));
215:   const lo = Math.min(...candles.map((c) => c.l));
216:   const vol = candles.reduce((a, c) => a + (c.v || 0), 0);
217:   const prev = meta && meta.prevClose != null ? meta.prevClose : first.o;
218:   const chg = last.c - prev;
219:   const chgPct = prev ? (chg / prev) * 100 : 0;
220:   const dec = last.c < 1000 ? 2 : last.c < 100000 ? 2 : 0;
221: 
222:   $("price").textContent = fmtN(last.c, dec);
223:   const chgEl = $("chg");
224:   chgEl.textContent = `${chg >= 0 ? "+" : ""}${fmtN(chg, dec)} (${chgPct >= 0 ? "+" : ""}${chgPct.toFixed(2)}%)`;
225:   chgEl.className = "chg " + (chg >= 0 ? "pos" : "neg");
226: 
227:   const rows = [
228:     ["Open", fmtN(first.o, dec)],
229:     ["High", fmtN(hi, dec)],
230:     ["Low", fmtN(lo, dec)],
231:     ["Prev close", fmtN(prev, dec)],
232:     ["Volume", fmtBig(vol)],
233:     ["Points", String(candles.length)],
234:   ];
235:   $("stats").innerHTML = rows.map(([k, v]) => `<div class="stat"><div class="k">${k}</div><div class="v">${v}</div></div>`).join("");
236: }
237: 
238: async function refreshChart() {
239:   chartMsg("chartMsg", "Loading chart…");
240:   $("fallbackNote").hidden = true;
241:   try {
242:     const { candles, note } = await loadCandles(sym, tfKey);
243:     if (!candles.length) throw new Error("empty dataset");
244:     $("symName").textContent = symNames[sym.code] || sym.name;
245:     $("symCode").textContent = sym.code;
246:     if (note) { $("fallbackNote").hidden = false; $("fallbackNote").textContent = note; }
247:     drawChart(candles);
248:     renderStats(candles, null);
249:     chartMsg("chartMsg", null);
250:     try { localStorage.setItem("fakm_sym", JSON.stringify(sym)); localStorage.setItem("fakm_tf", tfKey); } catch {}
251:   } catch (e) {
252:     chartMsg("chartMsg", "Could not load chart data right now (" + e.message + "). Try again in a minute.");
253:   }
254: }
255: 
256: /* ---------------- search ---------------- */
257: let searchTimer = null;
258: function initSearch() {
259:   const input = $("search"), box = $("results");
260:   input.addEventListener("input", () => {
261:     clearTimeout(searchTimer);
262:     const q = input.value.trim();
263:     if (q.length < 2) { box.hidden = true; return; }
264:     searchTimer = setTimeout(async () => {
265:       try {
266:         const r = await api("/api/markets/search?q=" + encodeURIComponent(q));
267:         const results = (r && r.results) || [];
268:         if (!results.length) { box.hidden = true; return; }
269:         box.innerHTML = results.map((x, i) =>
270:           `<button data-i="${i}"><b>${String(x.symbol || "").toUpperCase()}</b><span>${x.name || ""}${x.rank ? " · #" + x.rank : ""}</span></button>`
271:         ).join("");
272:         box.hidden = false;
273:         box.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
274:           const x = results[+b.dataset.i];
275:           const code = String(x.symbol || "").toUpperCase();
276:           sym = { code, name: x.name || code, kind: "crypto" };
277:           symNames[code] = x.name || code;
278:           box.hidden = true; input.value = "";
279:           document.querySelectorAll(".chip").forEach((c) => c.classList.remove("on"));
280:           showChartView();
281:           refreshChart();
282:         }));
283:       } catch { box.hidden = true; }
284:     }, 300);
285:   });
286:   document.addEventListener("click", (e) => { if (!e.target.closest(".searchbox")) box.hidden = true; });
287: }
288: 
289: /* ---------------- mobile tabbed interface ----------------
290:  * On phones the page becomes a tabbed app: the bottom tab bar flips
291:  * body[data-mview] between the chart, market and insights sections.
292:  * Desktop never sets data-mview, so it renders exactly as before. */
293: const mobileMQ = window.matchMedia("(max-width:760px)");
294: let setMobileView = null;
295: function initMobileTabs() {
296:   const bar = $("tabbar");
297:   const go = (v) => {
298:     document.body.dataset.mview = v;
299:     bar.querySelectorAll("button").forEach((b) => b.classList.toggle("on", b.dataset.view === v));
300:     try { localStorage.setItem("fakm_mview", v); } catch {}
301:     if (v === "chart" && typeof chart !== "undefined" && chart && window.LightweightCharts) {
302:       requestAnimationFrame(() => { const z = chartSize(); chart.applyOptions({ width: z.width, height: z.height }); });
303:     }
304:     window.scrollTo({ top: 0 });
305:   };
306:   setMobileView = go;
307:   bar.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => go(b.dataset.view)));
308:   const apply = () => {
309:     if (!mobileMQ.matches) { document.body.removeAttribute("data-mview"); return; }
310:     let v = "chart";
311:     try { v = localStorage.getItem("fakm_mview") || "chart"; } catch {}
312:     if (!bar.querySelector('button[data-view="' + v + '"]')) v = "chart";
313:     go(v);
314:   };
315:   if (mobileMQ.addEventListener) mobileMQ.addEventListener("change", apply);
316:   apply();
317: }
318: function showChartView() {
319:   if (setMobileView && mobileMQ.matches) setMobileView("chart");
320: }
321: 
322: /* ---------------- chrome: chips + timeframe bar ---------------- */
323: function initChrome() {
324:   const chips = $("chips");
325:   chips.innerHTML = PRESETS.map((g) =>
326:     `<div class="chip-group"><span class="chip-label">${g.group}</span>` +
327:     g.items.map((s, i) => `<button class="chip" data-g="${g.group}" data-i="${i}">${s.code}</button>`).join("") + `</div>`
328:   ).join("");
329:   chips.querySelectorAll(".chip").forEach((b) => b.addEventListener("click", () => {
330:     const s = PRESETS.find((g) => g.group === b.dataset.g).items[+b.dataset.i];
331:     sym = s;
332:     chips.querySelectorAll(".chip").forEach((c) => c.classList.remove("on"));
333:     b.classList.add("on");
334:     refreshChart();
335:   }));
336:   const mark = () => chips.querySelectorAll(".chip").forEach((b) => {
337:     const s = PRESETS.find((g) => g.group === b.dataset.g).items[+b.dataset.i];
338:     b.classList.toggle("on", s.code === sym.code && s.group !== undefined);
339:   });
340: 
341:   const tfBar = $("tfBar");
342:   tfBar.innerHTML = Object.keys(TF).map((k) => `<button data-tf="${k}" class="${k === tfKey ? "on" : ""}">${k}</button>`).join("");
343:   tfBar.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
344:     tfKey = b.dataset.tf;
345:     tfBar.querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
346:     refreshChart();
347:   }));
348: 
349:   $("ctypeBar").querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
350:     chartType = b.dataset.ct;
351:     $("ctypeBar").querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
352:     refreshChart();
353:   }));
354:   mark();
355:   return mark;
356: }
357: 
358: /* ---------------- boot ---------------- */
359: async function boot() {
360:   initMobileTabs(); // no API dependency — tabs work even if the backend is down
361:   initZoomCtl();
362:   try {
363:     const v = await api("/api/version");
364:     if (!v || v.api !== "markets-api/v1") throw new Error("unexpected API");
365:   } catch (e) {
366:     chartMsg("chartMsg", "API unreachable — the Markets API isn't responding (" + e.message + "). Check your connection and reload.");
367:     return;
368:   }
369:   try {
370:     const s = JSON.parse(localStorage.getItem("fakm_sym") || "null");
371:     if (s && s.code) sym = s;
372:     const t = localStorage.getItem("fakm_tf");
373:     if (t && TF[t]) tfKey = t;
374:   } catch {}
375:   initChrome();
376:   initSearch();
377:   refreshChart();
378: }
379: 
380: document.addEventListener("DOMContentLoaded", () => boot());
381: 
382: /* ---------------- market overview ---------------- */
383: const mkt = { page: 1, maxPage: 4, sortKey: "rank", sortDir: 1, rows: [], updatedAt: 0, timer: null, query: "" };
384: 
385: const fmtPx = (p) => {
386:   if (p == null || !Number.isFinite(p)) return "—";
387:   if (p >= 1000) return fmtN(p, 2);
388:   if (p >= 1) return fmtN(p, p < 10 ? 4 : 2);
389:   return Number(p.toPrecision(4)).toString();
390: };
391: const fmtPct = (v) => {
392:   if (v == null || !Number.isFinite(v)) return '<span class="muted">—</span>';
393:   const cls = v >= 0 ? "pos" : "neg";
394:   return `<span class="${cls}">${v >= 0 ? "+" : ""}${v.toFixed(2)}%</span>`;
395: };
396: 
397: /* Deterministic hue for a coin's identicon badge (0-359). */
398: function hashHue(s) {
399:   let h = 0;
400:   for (const ch of String(s || "?")) h = (h * 31 + ch.charCodeAt(0)) % 360;
401:   return h;
402: }
403: /* Coin badge: artwork is proxied through our own API origin
404:  * (/api/markets/icon?sym=BTC) so no upstream host ever leaks; if the
405:  * artwork fails, the letter identicon underneath remains. */
406: function coinBadge(symU, small) {
407:   const letter = String(symU || "?").replace(/[^A-Z0-9]/gi, "").slice(0, 1).toUpperCase() || "?";
408:   const img = `<img src="${API}/api/markets/icon?sym=${encodeURIComponent(symU)}" data-sym="${symU}" loading="lazy" alt="" onerror="iconFallback(this)">`;
409:   return `<span class="ident${small ? " sm" : ""}" style="--h:${hashHue(symU)}" aria-hidden="true">${img}<b>${letter}</b></span>`;
410: }
411: function iconFallback(el) {
412:   el.remove(); // no artwork -> letter badge shows through
413: }
414: 
415: /* Inline SVG sparkline from the API's 7d price array. Same footprint as
416:  * the reference's sparkline image so the layout matches pixel for pixel. */
417: function sparkSVG(points) {
418:   const W = 110, H = 32, P = 3;
419:   const lo = Math.min(...points), hi = Math.max(...points), span = (hi - lo) || 1;
420:   const n = points.length;
421:   const d = points.map((v, i) =>
422:     `${(P + (i / (n - 1)) * (W - 2 * P)).toFixed(1)},${(P + (1 - (v - lo) / span) * (H - 2 * P)).toFixed(1)}`
423:   ).join(" ");
424:   const up = points[n - 1] >= points[0];
425:   const col = up ? "#16a34a" : "#E30613";
426:   return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><polyline points="${d}" fill="none" stroke="${col}" stroke-width="1.6"/></svg>`;
427: }
428: 
429: function chartCoin(symU, name) {
430:   if (!symU) return;
431:   sym = { code: symU, name: name || symU, kind: "crypto" };
432:   symNames[symU] = name || symU;
433:   document.querySelectorAll(".chip").forEach((c) => c.classList.remove("on"));
434:   showChartView();
435:   window.scrollTo({ top: 0, behavior: "smooth" });
436:   refreshChart();
437: }
438: 
439: function renderMarket() {
440:   // insights always run on the full page rows; the search box only
441:   // filters the table itself
442:   renderInsights(mkt.rows);
443:   const q = (mkt.query || "").trim().toLowerCase();
444:   const pool = q ? mkt.rows.filter((c) =>
445:     String(c.name || "").toLowerCase().includes(q) ||
446:     String(c.symbol || "").toLowerCase().includes(q)) : mkt.rows;
447:   const rows = [...pool].sort((a, b) => {
448:     const av = a[mkt.sortKey] ?? -Infinity, bv = b[mkt.sortKey] ?? -Infinity;
449:     return (av - bv) * mkt.sortDir;
450:   });
451:   $("mktBody").innerHTML = rows.map((c) => {
452:     const symU = String(c.symbol || "").toUpperCase();
453:     return `<tr data-sym="${symU}" data-name="${(c.name || "").replace(/"/g, "")}">
454:       <td class="muted">${c.rank ?? "—"}</td>
455:       <td><span class="coin-cell">${coinBadge(symU)}<span>${c.name || "—"} <span class="csym">${symU}</span></span></span></td>
456:       <td class="num"><b>${fmtPx(c.price_usd)}</b></td>
