499: function drawDoughnut(canvas, shares) {
500:   const dpr = window.devicePixelRatio || 1;
501:   const boxW = canvas.parentElement ? canvas.parentElement.getBoundingClientRect().width : 220;
502:   const size = Math.max(120, Math.min(210, Math.floor(boxW * 0.45) || 160));
503:   canvas.width = size * dpr;
504:   canvas.height = size * dpr;
505:   canvas.style.width = size + "px";
506:   canvas.style.height = size + "px";
507:   const ctx = canvas.getContext("2d");
508:   ctx.scale(dpr, dpr);
509:   ctx.clearRect(0, 0, size, size);
510:   const cx = size / 2, cy = size / 2, R = size / 2 - 4, r = R * 0.62;
511:   let a = -Math.PI / 2;
512:   shares.forEach((s, i) => {
513:     const a2 = a + (s.share / 100) * Math.PI * 2;
514:     ctx.beginPath();
515:     ctx.arc(cx, cy, R, a, a2);
516:     ctx.arc(cx, cy, r, a2, a, true);
517:     ctx.closePath();
518:     ctx.fillStyle = DIST_COLORS[i % DIST_COLORS.length];
519:     ctx.fill();
520:     a = a2;
521:   });
522:   ctx.textAlign = "center";
523:   ctx.fillStyle = "#6b7280";
524:   ctx.font = "600 11px Inter, sans-serif";
525:   ctx.fillText("TOP " + shares.length, cx, cy - 3);
526:   ctx.fillStyle = "#111";
527:   ctx.font = "700 12px Inter, sans-serif";
528:   ctx.fillText("MKT CAP", cx, cy + 13);
529: }
